// @FIGURE_CODE_BEGIN
// ELEMENT SPEC
// near-end parabolic profile  → THREE.Line (black) at z = L*FT (front in oblique)
// far-end parabolic profile   → THREE.Line (black) at z = 0
// rim/bottom connector edges  → 3 THREE.Line segments joining the two profiles along z
// trough side walls           → extruded strip BufferGeometry, light grey, opacity 0.18
// water surface               → PlaneGeometry(2*xc*IN, L*FT), #7ab8e0 opacity 0.5, at y = h*IN
// water fill in near end      → ShapeGeometry of profile region below h, #7ab8e0 opacity 0.5
// fill line on near end       → THREE.Line across the profile at y = h, #2270b0
// depth arrow                 → black line + 2 ConeGeometry arrowheads, rim→bottom, z = L*FT
// cross-section view (g2)     → black axis lines + ticks; dynamic parabola Line,
//                               top-width dots (SphereGeometry 0.02), blue fill line + dots
// labels                      → addLabel: '18 in', 'L ft', top-width 'in', axis + point labels

const IN = 0.1;          // world units per inch (cross section)
const FT = 1.0;          // world units per foot (length)
const FAR_POS = new THREE.Vector3(1e5, 1e5, 1e5);

const state = { h: 9, L: 3, view: '3D Trough', fn: null, src: 'x^2/8' };

const g3 = new THREE.Group();    // 3D trough group (rebuilt)
const g2 = new THREE.Group();    // cross-section group (static axes + dynamic subgroup)
const g2dyn = new THREE.Group();
g2.add(g2dyn);
scene.add(g3, g2);

const MAT_LINE = () => new THREE.LineBasicMaterial({ color: 0x111111 });
const MAT_BLUE_LINE = () => new THREE.LineBasicMaterial({ color: 0x2270b0 });
const MAT_WATER = () => new THREE.MeshBasicMaterial({ color: 0x7ab8e0, transparent: true, opacity: 0.5, side: THREE.DoubleSide, depthWrite: false });

function clearGroup(gr) {
  while (gr.children.length) {
    const c = gr.children[0];
    gr.remove(c);
    c.traverse(o => {
      o.geometry?.dispose?.();
      if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
      else o.material?.dispose?.();
    });
  }
}

/* ── profile sampling from the entered equation ── */
function profileSamples() {
  const N = 160, pts = [];
  const xt = xAt(18);
  const XMAX = xt ? Math.min(xt * 1.02, 9) : 7;
  for (let i = 0; i <= N; i++) {
    const x = -XMAX + 2 * XMAX * i / N;
    let y; try { y = state.fn(x); } catch { y = NaN; }
    if (!Number.isFinite(y)) y = 18;
    pts.push([x, Math.min(Math.max(y, 0), 18)]);
  }
  return pts;
}

// smallest positive x where fn(x) crosses level y (linear interpolation)
function xAt(y) {
  let f0; try { f0 = state.fn(0); } catch { return null; }
  if (!Number.isFinite(f0) || f0 >= y) return null;
  const N = 1400; let prev = f0 - y;
  for (let i = 1; i <= N; i++) {
    const x = 9 * i / N;
    let v; try { v = state.fn(x) - y; } catch { return null; }
    if (!Number.isFinite(v)) return null;
    if (prev <= 0 && v >= 0) {
      const x0 = 9 * (i - 1) / N;
      return x0 + (9 / N) * (0 - prev) / (v - prev);
    }
    prev = v;
  }
  return null;
}

function minProfileY() {
  let m = Infinity;
  for (let i = 0; i <= 400; i++) {
    const x = -7 + 14 * i / 400;
    let y; try { y = state.fn(x); } catch { continue; }
    if (Number.isFinite(y)) m = Math.min(m, y);
  }
  return m === Infinity ? 0 : Math.max(m, 0);
}

/* ── labels (created once, positions/text updated in rebuild) ── */
const lbls3 = [], lbls2 = [];
function mkLabel(set, html, pos, opts = {}) {
  const e = addLabel(html, pos, opts);
  e._home = pos.clone();
  set.push(e);
  return e;
}
const lbl18  = mkLabel(lbls3, '18 in', new THREE.Vector3(0.3, 0.9, 3), { bold: true });
const lblLen = mkLabel(lbls3, '3 ft', new THREE.Vector3(-0.6, 1.8, 1.5), { offset: [0, -16] });
const lblWid = mkLabel(lbls3, '12 in', new THREE.Vector3(0, 1.8, 0), { offset: [0, -16], bold: true });

mkLabel(lbls2, 'x (in)', new THREE.Vector3(1.0, -0.02, 0), { offset: [8, 12] });
mkLabel(lbls2, 'y (in)', new THREE.Vector3(0, 2.08, 0), { offset: [14, 0] });
mkLabel(lbls2, '18', new THREE.Vector3(0, 1.8, 0), { offset: [-14, 0], fontSize: '11px' });
mkLabel(lbls2, 'O', new THREE.Vector3(0, 0, 0), { offset: [-10, 10], fontSize: '11px' });
const lblEq   = mkLabel(lbls2, 'y = x^2/8', new THREE.Vector3(-0.55, 1.95, 0), { bold: true });
const lblH    = mkLabel(lbls2, 'h = 9 in', new THREE.Vector3(0.5, 0.9, 0), { color: '#2270b0', offset: [14, 0] });
const lblTopR = mkLabel(lbls2, '(6, 18)', new THREE.Vector3(0.6, 1.8, 0), { offset: [10, -12], fontSize: '11px' });
const lblTopL = mkLabel(lbls2, '(-6, 18)', new THREE.Vector3(-0.6, 1.8, 0), { offset: [-10, -12], fontSize: '11px' });

/* ── static 2D axes for cross-section view ── */
(function buildAxes() {
  const ax = new THREE.Line(new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(-0.95, 0, 0), new THREE.Vector3(0.98, 0, 0)]), MAT_LINE());
  const ay = new THREE.Line(new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 2.08, 0)]), MAT_LINE());
  g2.add(ax, ay);
  const tickPts = [];
  for (let i = -9; i <= 9; i += 3) tickPts.push(new THREE.Vector3(i * IN, -0.02, 0), new THREE.Vector3(i * IN, 0.02, 0));
  for (let j = 2; j <= 20; j += 2) tickPts.push(new THREE.Vector3(-0.02, j * IN, 0), new THREE.Vector3(0.02, j * IN, 0));
  g2.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(tickPts), MAT_LINE()));
})();

/* ── rebuild everything from current state ── */
function rebuild() {
  if (!state.fn) return;
  clearGroup(g3);
  clearGroup(g2dyn);

  const pts = profileSamples();               // [xIn, yIn] pairs
  const Lw = state.L * FT;
  const minY = minProfileY();
  const h = state.h;
  const xc = xAt(h);                          // water half-width (inches)
  const xt = xAt(18);                         // top half-width (inches)

  // end profile curves
  const near3 = pts.map(p => new THREE.Vector3(p[0] * IN, p[1] * IN, Lw));
  const far3  = pts.map(p => new THREE.Vector3(p[0] * IN, p[1] * IN, 0));
  g3.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(near3), MAT_LINE()));
  g3.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(far3), MAT_LINE()));

  // connector edges: left rim, right rim, bottom vertex
  let minIdx = 0;
  pts.forEach((p, i) => { if (p[1] < pts[minIdx][1]) minIdx = i; });
  for (const idx of [0, pts.length - 1, minIdx]) {
    g3.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([near3[idx], far3[idx]]), MAT_LINE()));
  }

  // side walls (extruded strip)
  {
    const Nv = pts.length;
    const pos = new Float32Array(Nv * 2 * 3);
    pts.forEach((p, i) => {
      pos.set([p[0] * IN, p[1] * IN, Lw], i * 6);
      pos.set([p[0] * IN, p[1] * IN, 0], i * 6 + 3);
    });
    const idxArr = [];
    for (let i = 0; i < Nv - 1; i++) {
      const a = i * 2, b = i * 2 + 1, c = i * 2 + 2, d2 = i * 2 + 3;
      idxArr.push(a, b, c, b, d2, c);
    }
    const wg = new THREE.BufferGeometry();
    wg.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    wg.setIndex(idxArr);
    wg.computeVertexNormals();
    g3.add(new THREE.Mesh(wg, new THREE.MeshBasicMaterial({ color: 0x888888, transparent: true, opacity: 0.15, side: THREE.DoubleSide, depthWrite: false })));
  }

  // water
  if (xc !== null && h > minY + 1e-6) {
    const surf = new THREE.Mesh(new THREE.PlaneGeometry(2 * xc * IN, Lw), MAT_WATER());
    surf.rotation.x = -Math.PI / 2;
    surf.position.set(0, h * IN, Lw / 2);
    g3.add(surf);

    // fill region in near-end cross section
    const shape = new THREE.Shape();
    shape.moveTo(-xc * IN, h * IN);
    pts.forEach(p => { if (p[1] <= h) shape.lineTo(p[0] * IN, p[1] * IN); });
    shape.lineTo(xc * IN, h * IN);
    shape.closePath();
    const fill = new THREE.Mesh(new THREE.ShapeGeometry(shape), MAT_WATER());
    fill.position.z = Lw + 0.002;
    g3.add(fill);

    // fill line on near end
    g3.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(-xc * IN, h * IN, Lw + 0.004), new THREE.Vector3(xc * IN, h * IN, Lw + 0.004)]), MAT_BLUE_LINE()));
  }

  // depth arrow (double-headed) inside near end
  {
    const zA = Lw + 0.006, y0 = minY * IN, y1 = 18 * IN;
    g3.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(0, y0, zA), new THREE.Vector3(0, y1, zA)]), MAT_LINE()));
    const cTop = new THREE.Mesh(new THREE.ConeGeometry(0.035, 0.1, 12), new THREE.MeshBasicMaterial({ color: 0x111111 }));
    cTop.position.set(0, y1, zA);
    const cBot = cTop.clone();
    cBot.rotation.z = Math.PI;
    cBot.position.set(0, y0, zA);
    g3.add(cTop, cBot);
  }

  // 3D labels
  lbl18.pos.set(0.28, 0.9, Lw); lbl18._home.copy(lbl18.pos);
  lblLen.div.innerHTML = `<b>${state.L} ft</b>`;
  lblLen.pos.set(near3[0].x, near3[0].y, Lw / 2); lblLen._home.copy(lblLen.pos);
  lblWid.div.innerHTML = `<b>${xt ? (2 * xt).toFixed(0) : '?'} in</b>`;
  lblWid.pos.set((far3[0].x + far3[far3.length - 1].x) / 2, Math.max(far3[0].y, far3[far3.length - 1].y), 0);
  lblWid._home.copy(lblWid.pos);

  /* ── cross-section dynamic content ── */
  const curve2 = pts.filter(p => p[1] <= 20).map(p => new THREE.Vector3(p[0] * IN, p[1] * IN, 0));
  g2dyn.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(curve2), MAT_LINE()));
  const dotMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
  if (xt !== null) {
    for (const s of [-1, 1]) {
      const d = new THREE.Mesh(new THREE.SphereGeometry(0.02, 12, 8), dotMat);
      d.position.set(s * xt * IN, 1.8, 0);
      g2dyn.add(d);
    }
    lblTopR.div.innerHTML = `(${xt.toFixed(1)}, 18)`;
    lblTopL.div.innerHTML = `(${(-xt).toFixed(1)}, 18)`;
