  body: 'The trough walls are the entered profile y = f(x) extruded along the length L. ' +
        'The water surface width at depth h is 2x where f(x) = h — for y = x²/8 that is 2√(8h). ' +
        'Surface area = width(h) × L, so it grows with depth even though the length is fixed.'
});

/* ── demo steps ── */
const steps = [
  { title: 'The trough at half depth', narration: 'The 3 ft trough is filled to h = 9 in. The blue water surface is narrower than the 12 in top rim — width depends on depth.', state: { waterDepth: 9, troughLength: 3, viewMode: '3D Trough' } },
  { title: 'Fill to the top', narration: 'Raise the depth to 18 in. The water surface now spans the full 12 in top width, matching the labeled dimension.', state: { waterDepth: 18, troughLength: 3, viewMode: '3D Trough' } },
  { title: 'Fit the cross-section', narration: 'With vertex at the origin, y = ax² through (6, 18) gives a = 18/36 = 1/2... i.e. 18 = a·36, so a = 1/2 and y = x²/2·(1/4) = x²/8. The fill line at h shows width 2√(8h).', state: { waterDepth: 9, troughLength: 3, viewMode: 'Cross-Section' } },
  { title: 'Change the length', narration: 'Back in 3D, extend the trough to 6 ft. The cross-section and water width are unchanged; only the surface rectangle lengthens, doubling the surface area.', state: { waterDepth: 9, troughLength: 6, viewMode: '3D Trough' } },
];
let stepIdx = -1, tweenId = 0;
function goToStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  const s = steps[stepIdx];
  document.getElementById('demoTitle').textContent = `${stepIdx + 1}/${steps.length}: ${s.title}`;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('viewMode').value = s.state.viewMode;
  state.view = s.state.viewMode;
  applyViewVisibility(); applyViewCam();
  const myTween = ++tweenId;
  const h0 = state.h, l0 = state.L, h1 = s.state.waterDepth, l1 = s.state.troughLength, t0 = performance.now();
  (function tick() {
    if (myTween !== tweenId) return;
    const k = Math.min(1, (performance.now() - t0) / 700);
    const e = k * (2 - k);
    state.h = h0 + (h1 - h0) * e;
    state.L = l0 + (l1 - l0) * e;
    hSlider.value = state.h; lSlider.value = state.L;
    hRead.textContent = Math.round(state.h * 2) / 2;
    lRead.textContent = Math.round(state.L * 2) / 2;
    rebuild();
    if (k < 1) requestAnimationFrame(tick);
  })();
}
document.getElementById('btnPrevStep').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNextStep').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── initial camera (all geometry is in the scene now) ── */
applyViewCam();
