  { title: 'Fill to the top', narration: 'Raise the depth to 18 in. The water surface now spans the full 12 in top width, exactly matching the labeled dimensions.', state: { waterDepth: 18, troughLength: 3, viewMode: '3D Trough' } },
  { title: 'Fit the cross-section', narration: 'With the vertex at the origin, try y = ax². The rim passes through (6, 18): 18 = a·36, so a = 1/2 and the profile is y = x²/2. At depth h the width is 2√(2h).', state: { waterDepth: 9, troughLength: 3, viewMode: 'Cross-Section' } },
