function clearGroup(gr) {
  while (gr.children.length) {
    const c = gr.children[0];
    gr.remove(c);
    c.traverse(o => {
      o.geometry?.dispose?.();
      if (Array.isArray(o.material)) o.material.forEach(m => m.dispose?.());
      else o.material?.dispose?.();
    });
  }
}

/* ── profile sampling from the entered equation ── */
function xAt(y) {
  let f0; try { f0 = state.fn(0); } catch { return null; }
  if (!Number.isFinite(f0) || f0 >= y) return null;
  const N = 1400; let prev = f0 - y;
  for (let i = 1; i <= N; i++) {
    const x = 12 * i / N;
    let v; try { v = state.fn(x) - y; } catch { return null; }
    if (!Number.isFinite(v)) return null;
    if (prev <= 0 && v >= 0) {
      const x0 = 12 * (i - 1) / N;
      return x0 + (12 / N) * (0 - prev) / (v - prev);
    }
    prev = v;
  }
  return null;
}

function profileSamples() {
  const N = 200, pts = [];
  const xt = xAt(18);
  const XMAX = xt !== null ? xt : 8;
  for (let i = 0; i <= N; i++) {
    const x = -XMAX + 2 * XMAX * i / N;
    let y; try { y = state.fn(x); } catch { y = NaN; }
    if (!Number.isFinite(y)) y = 18;
    pts.push([x, Math.max(y, 0)]);
  }
  return pts;
}

function minProfileY() {
  let m = Infinity;
  for (let i = 0; i <= 400; i++) {
    const x = -8 + 16 * i / 400;
    let y; try { y = state.fn(x); } catch { continue; }
    if (Number.isFinite(y)) m = Math.min(m, y);
  }
  return m === Infinity ? 0 : Math.max(m, 0);
}

