const lblEq   = mkLabel(lbls2, 'y = x^2/2', new THREE.Vector3(-0.6, 2.35, 0), { bold: true });
const lblH    = mkLabel(lbls2, 'h = 9 in', new THREE.Vector3(0.5, 1.1, 0), { color: '#2270b0', offset: [14, 0] });
const lblTopR = mkLabel(lbls2, '(6, 18)', new THREE.Vector3(0.72, 2.16, 0), { offset: [12, -12], fontSize: '11px' });
const lblTopL = mkLabel(lbls2, '(-6, 18)', new THREE.Vector3(-0.72, 2.16, 0), { offset: [-12, -12], fontSize: '11px' });

/* ── static 2D axes for cross-section view ── */
(function buildAxes() {
  const ax = new THREE.Line(new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(-1.1, 0, 0), new THREE.Vector3(1.15, 0, 0)]), MAT_LINE());
  const ay = new THREE.Line(new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 2.45, 0)]), MAT_LINE());
  g2.add(ax, ay);
  const tickPts = [];
  for (let i = -9; i <= 9; i += 3) tickPts.push(new THREE.Vector3(i * IN, -0.02, 0), new THREE.Vector3(i * IN, 0.02, 0));
  for (let j = 2; j <= 20; j += 2) tickPts.push(new THREE.Vector3(-0.02, j * IN, 0), new THREE.Vector3(0.02, j * IN, 0));
  g2.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(tickPts), MAT_LINE()));
})();

/* ── rebuild everything from current state ── */
function rebuild() {
  if (!state.fn) return;
  clearGroup(g3);
  g3.add(gWater);
  clearGroup(gWater);
  clearGroup(g2dyn);

  const pts = profileSamples();
  const Lw = state.L * FT;
  const minY = minProfileY();
  const h = state.h;
  const xc = xAt(h);
  const xt = xAt(18);

  // near end faces the viewer (z = Lw); far end recedes (z = 0)
  const near3 = pts.map(p => new THREE.Vector3(p[0] * IN, p[1] * IN, Lw));
  const far3  = pts.map(p => new THREE.Vector3(p[0] * IN, p[1] * IN, 0));
  g3.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(near3), MAT_LINE()));
  g3.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(far3), MAT_LINE()));

  // bottom vertex connector
  let minIdx = 0;
  pts.forEach((p, i) => { if (p[1] < pts[minIdx][1]) minIdx = i; });
  g3.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints([near3[minIdx], far3[minIdx]]), MAT_LINE()));

  // EMPHASIZED top rim rectangle: bold bars along both rims and across both end tops
  const nL = near3[0], nR = near3[near3.length - 1];
  const fL = far3[0],  fR = far3[far3.length - 1];
  g3.add(rimBar(nL, fL));
  g3.add(rimBar(nR, fR));
  g3.add(rimBar(fL, fR));
  g3.add(rimBar(nL, nR));

  // side walls (extruded strip)
  {
    const Nv = pts.length;
    const pos = new Float32Array(Nv * 2 * 3);
    pts.forEach((p, i) => {
      pos.set([p[0] * IN, p[1] * IN, Lw], i * 6);
      pos.set([p[0] * IN, p[1] * IN, 0], i * 6 + 3);
    });
    const idxArr = [];
    for (let i = 0; i < Nv - 1; i++) {
      const a = i * 2, b = i * 2 + 1, c = i * 2 + 2, dd = i * 2 + 3;
      idxArr.push(a, b, c, b, dd, c);
    }
    const wg = new THREE.BufferGeometry();
    wg.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    wg.setIndex(idxArr);
    wg.computeVertexNormals();
    g3.add(new THREE.Mesh(wg, new THREE.MeshBasicMaterial({ color: 0x888888, transparent: true, opacity: 0.15, side: THREE.DoubleSide, depthWrite: false })));
  }

  // water (only when enabled — default view matches the empty dimensioned source)
  if (state.water && xc !== null && h > minY + 1e-6) {
    const surf = new THREE.Mesh(new THREE.PlaneGeometry(2 * xc * IN, Lw), MAT_WATER());
    surf.rotation.x = -Math.PI / 2;
    surf.position.set(0, h * IN, Lw / 2);
    gWater.add(surf);

    const shape = new THREE.Shape();
    shape.moveTo(-xc * IN, h * IN);
    pts.forEach(p => { if (p[1] <= h) shape.lineTo(p[0] * IN, p[1] * IN); });
    shape.lineTo(xc * IN, h * IN);
    shape.closePath();
    const fill = new THREE.Mesh(new THREE.ShapeGeometry(shape), MAT_WATER());
    fill.position.z = Lw + 0.002;
    gWater.add(fill);

    gWater.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(-xc * IN, h * IN, Lw + 0.004), new THREE.Vector3(xc * IN, h * IN, Lw + 0.004)]), MAT_BLUE_LINE()));
  }

  // depth arrow (double-headed) inside near end — matches the source's 18 in arrow
  {
    const zA = Lw + 0.006, y0 = minY * IN, y1 = 18 * IN;
    g3.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(0, y0, zA), new THREE.Vector3(0, y1, zA)]), MAT_LINE()));
    const cTop = new THREE.Mesh(new THREE.ConeGeometry(0.04, 0.11, 12), new THREE.MeshBasicMaterial({ color: 0x111111 }));
    cTop.position.set(0, y1, zA);
    const cBot = cTop.clone();
    cBot.rotation.z = Math.PI;
    cBot.position.set(0, y0, zA);
    g3.add(cTop, cBot);
  }

  // 3D labels
  lbl18.pos.set(0.34, 1.05, Lw); lbl18._home.copy(lbl18.pos);
  lblLen.div.innerHTML = `<b>${state.L} ft</b>`;
  lblLen.pos.set(fL.x, fL.y + 0.02, Lw / 2); lblLen._home.copy(lblLen.pos);
  lblWid.div.innerHTML = `<b>${xt !== null ? Math.round(2 * xt) : '?'} in</b>`;
  lblWid.pos.set((fL.x + fR.x) / 2, Math.max(fL.y, fR.y), 0);
  lblWid._home.copy(lblWid.pos);

  /* ── cross-section dynamic content ── */
  const curve2 = pts.filter(p => p[1] <= 20).map(p => new THREE.Vector3(p[0] * IN, p[1] * IN, 0));
  g2dyn.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(curve2), MAT_LINE()));
  const dotMat = new THREE.MeshBasicMaterial({ color: 0x111111 });
  if (xt !== null) {
    for (const s of [-1, 1]) {
      const dt = new THREE.Mesh(new THREE.SphereGeometry(0.025, 12, 8), dotMat);
      dt.position.set(s * xt * IN, 2.16, 0);
      g2dyn.add(dt);
    }
    lblTopR.div.innerHTML = `(${+xt.toFixed(1)}, 18)`;
    lblTopL.div.innerHTML = `(${+(-xt).toFixed(1)}, 18)`;
    lblTopR.pos.set(xt * IN, 2.16, 0); lblTopR._home.copy(lblTopR.pos);
    lblTopL.pos.set(-xt * IN, 2.16, 0); lblTopL._home.copy(lblTopL.pos);
  } else {
    lblTopR.div.innerHTML = ''; lblTopL.div.innerHTML = '';
  }
  if (xc !== null && h > minY + 1e-6) {
    g2dyn.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(
      [new THREE.Vector3(-xc * IN, h * IN, 0.001), new THREE.Vector3(xc * IN, h * IN, 0.001)]), MAT_BLUE_LINE()));
    const bdMat = new THREE.MeshBasicMaterial({ color: 0x2270b0 });
    for (const s of [-1, 1]) {
      const dt = new THREE.Mesh(new THREE.SphereGeometry(0.025, 12, 8), bdMat);
      dt.position.set(s * xc * IN, h * IN, 0.001);
      g2dyn.add(dt);
    }
    lblH.div.innerHTML = `h = ${h} in, w = ${(2 * xc).toFixed(1)} in`;
    lblH.pos.set(xc * IN, h * IN, 0); lblH._home.copy(lblH.pos);
  } else {
    lblH.div.innerHTML = `h = ${h} in (below curve)`;
    lblH.pos.set(0.3, Math.max(h, 1) * IN, 0); lblH._home.copy(lblH.pos);
  }
  lblEq.div.innerHTML = `y = ${state.src}`;

  applyViewVisibility();
}

/* ── view toggling ── */
function applyViewVisibility() {
  const is3D = state.view === '3D Trough';
  g3.visible = is3D; g3.scale.setScalar(is3D ? 1 : 1e-6);
  g2.visible = !is3D; g2.scale.setScalar(is3D ? 1e-6 : 1);
  gWater.visible = state.water;
  for (const e of lbls3) e.pos.copy(is3D ? e._home : FAR_POS);
  for (const e of lbls2) e.pos.copy(is3D ? FAR_POS : e._home);
}
function applyViewCam() {
  const Lw = state.L * FT;
  if (state.view === '3D Trough') {
    // oblique, front-on at the near parabolic end; shallow 12° recession keeps the
    // length axis nearly horizontal so the trough lies left-to-right like the source
    setCameraView({
      projection: 'oblique', obliqueAngleDeg: 12, depthScale: 0.45,
      target: [0.15, 1.0, Lw * 0.55], heightFraction: 0.66,
    });
  } else {
    setCameraView({ projection: 'orthographic', azimuthDeg: 90, elevationDeg: 0, target: [0, 1.1, 0], heightFraction: 0.82 });
  }
}

/* ── controls ── */
const hSlider = document.getElementById('waterDepth');
const lSlider = document.getElementById('troughLength');
const hRead = document.getElementById('hReadout');
const lRead = document.getElementById('lReadout');
const waterChk = document.getElementById('showWater');

hSlider.addEventListener('input', () => {
  state.h = parseFloat(hSlider.value);
  hRead.textContent = state.h;
  rebuild();
});
lSlider.addEventListener('input', () => {
  state.L = parseFloat(lSlider.value);
  lRead.textContent = state.L;
  rebuild();
  if (state.view === '3D Trough') applyViewCam();
});
waterChk.addEventListener('change', () => {
  state.water = waterChk.checked;
  applyViewVisibility();
  rebuild();
});
document.getElementById('viewMode').addEventListener('change', (e) => {
  state.view = e.target.value;
  applyViewVisibility();
  applyViewCam();
});

// equation input drives BOTH the 3D trough geometry and the 2D graph
bindEquationInput('profile', (fn, src) => {
  state.fn = fn; state.src = src;
  rebuild();
}, { variables: ['x'] });

/* ── interactivity explanations ── */
registerInteractive(g3, {
  title: 'Parabolic trough',
  tooltip: 'Trough: cross-section from y = f(x)',
  body: 'The trough walls are the entered profile y = f(x) extruded along the length L. ' +
        'The bold rectangle on top is the rim: 12 in wide × 3 ft long. The water surface width ' +
        'at depth h is 2x where f(x) = h — for y = x²/2 that is 2√(2h), giving the full 12 in ' +
        'top width at h = 18 in. Check "Show water fill" to see the surface.'
});

/* ── demo steps ── */
const steps = [
  { title: 'The dimensioned trough', narration: 'The empty trough matches the figure: a parabolic end 18 in deep and 12 in across the top, 3 ft long. The bold rim rectangle marks the opening.', state: { waterDepth: 9, troughLength: 3, viewMode: '3D Trough', water: false } },
  { title: 'Fill it halfway', narration: 'Water added to h = 9 in. The blue surface is narrower than the 12 in rim — the width depends on the depth through f(x) = h.', state: { waterDepth: 9, troughLength: 3, viewMode: '3D Trough', water: true } },
  { title: 'Fill to the top', narration: 'At h = 18 in the water surface spans the full 12 in top width, exactly matching the labeled dimensions.', state: { waterDepth: 18, troughLength: 3, viewMode: '3D Trough', water: true } },
  { title: 'Fit the cross-section', narration: 'With the vertex at the origin, try y = ax². The rim passes through (6, 18): 18 = a·36, so a = 1/2 and the profile is y = x²/2. At depth h the width is 2√(2h).', state: { waterDepth: 9, troughLength: 3, viewMode: 'Cross-Section', water: true } },
  { title: 'Change the length', narration: 'Back in 3D, extend the trough to 6 ft. The cross-section and water width are unchanged; only the surface rectangle lengthens, doubling the water surface area.', state: { waterDepth: 9, troughLength: 6, viewMode: '3D Trough', water: true } },
];
let stepIdx = -1, tweenId = 0;
function goToStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  const s = steps[stepIdx];
  document.getElementById('demoTitle').textContent = `${stepIdx + 1}/${steps.length}: ${s.title}`;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('viewMode').value = s.state.viewMode;
  state.view = s.state.viewMode;
  state.water = s.state.water;
  waterChk.checked = s.state.water;
  applyViewVisibility(); applyViewCam();
  const myTween = ++tweenId;
  const h0 = state.h, l0 = state.L, h1 = s.state.waterDepth, l1 = s.state.troughLength, t0 = performance.now();
  (function tick() {
    if (myTween !== tweenId) return;
    const k = Math.min(1, (performance.now() - t0) / 700);
    const e = k * (2 - k);
    state.h = h0 + (h1 - h0) * e;
    state.L = l0 + (l1 - l0) * e;
    hSlider.value = state.h; lSlider.value = state.L;
    hRead.textContent = Math.round(state.h * 2) / 2;
    lRead.textContent = Math.round(state.L * 2) / 2;
    rebuild();
    if (k < 1) requestAnimationFrame(tick);
  })();
}
document.getElementById('btnPrevStep').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNextStep').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── initial camera (all geometry is in the scene now) ── */
applyViewCam();
